mapper.select:
SELECT COUNT(*)

    FROM shopwizard.tShpShipDirectPrint SD
    FROM shopwizard.tShpShipDirect SD

INNER JOIN shopwizard.tCmpChnl Ch ON SD.ChnlCode = Ch.ChnlCode
INNER JOIN shopwizard.tCmpShop S ON SD.ShopCode = S.ShopCode

    LEFT OUTER JOIN shopwizard.tCmpDeliComp DC ON SD.DeliCompCode = DC.DeliCompCode

WHERE (SD.ShipCancelRqstDate IS NULL OR SD.ShipCancelRqstDate = '')
AND (SD.ShipCancelCmpletDate IS NULL OR SD.ShipCancelCmpletDate = '')
AND Ch.SvcCode = #{pSvcCode}


        AND (SD.ShipCmpletDate IS NOT NULL AND SD.ShipCmpletDate != '') AND (SD.DeliCmpletDate IS NULL OR SD.DeliCmpletDate = '')



            AND (SD.ShipCheckDate IS NOT NULL AND SD.ShipCheckDate != '') AND (SD.InvNo IS NULL OR SD.InvNo = '')


            AND (SD.ShipCheckDate IS NULL OR SD.ShipCheckDate = '')





    AND (
        SD.ShipCheckDate >= DATE_FORMAT(#{pShipCheckStartDate}, '%Y-%m-%d') AND
        SD.ShipCheckDate <  ADDDATE(DATE_FORMAT(#{pShipCheckEndDate}, '%Y-%m-%d'), INTERVAL 1 DAY)
    )


AND SD.OrderNo = #{pOrderNo}
AND SD.OrderProdNo = #{pOrderProdNo}
AND SD.OrderChangeNo = #{pOrderChangeNo}
AND OrderType = #{pOrderType}
AND SD.ShopCode = #{pShopCode}
AND S.MngrMd = #{pShopMDCode}
AND SD.OrderName LIKE CONCAT('%',#{pOrderName},'%')
AND SD.ChnlCode = #{pChnlCode}
AND Ch.ChnlName IN ('쿠팡','위메프','위메프D','위메프 파트너2.0','티몬','티몬(shopion)')
AND Ch.ChnlName NOT IN ('쿠팡','위메프','위메프D','위메프 파트너2.0','티몬','티몬(shopion)')

    AND Ch.ChnlName NOT IN ('홈앤쇼핑')
    AND Ch.ChnlName IN ('홈앤쇼핑')

AND SD.ShipCheckDate = #{pShipCheckDate}

SELECT SD.*, Ch.ChnlName, DC.LinkUrl, DC.InvNoVar, O.OrderReciptDate
FROM shopwizard.tShpShipDirect SD
INNER JOIN shopion.tOrdOrder O ON SD.OrderNo = O.OrderNo
INNER JOIN shopwizard.tCmpChnl Ch ON SD.ChnlCode = Ch.ChnlCode
LEFT OUTER JOIN shopwizard.tCmpDeliComp DC ON SD.DeliCompCode = DC.DeliCompCode
WHERE SD.OrderNo = #{orderNo}
AND SD.OrderProdNo = #{orderProdNo}
AND SD.OrderChangeNo = #{orderChangeNo}

SELECT SD.*, '' AS ChnlName, '' AS LinkUrl, '' AS InvNoVar, '' AS OrderReciptDate
FROM shopwizard.tShpShipDirect SD
WHERE SD.OrderNo = #{orderNo}
AND SD.OrderProdNo = #{orderProdNo}
AND SD.OrderChangeNo = #{orderChangeNo}

SELECT DISTINCT IFNULL(SD.ShipPlace,'기본출고지') AS ShipPlace
FROM shopwizard.tShpShipDirectPrint SD
INNER JOIN shopwizard.tCmpChnl Ch ON SD.ChnlCode = Ch.ChnlCode
WHERE (SD.ShipCancelRqstDate IS NULL OR SD.ShipCancelRqstDate = '')
AND (SD.ShipCancelCmpletDate IS NULL OR SD.ShipCancelCmpletDate = '')
AND Ch.SvcCode = #{pSvcCode}


        AND (SD.ShipCmpletDate IS NOT NULL AND SD.ShipCmpletDate != '') AND (SD.DeliCmpletDate IS NULL OR SD.DeliCmpletDate = '')



            AND (SD.ShipCheckDate IS NOT NULL AND SD.ShipCheckDate != '') AND (SD.InvNo IS NULL OR SD.InvNo = '')


            AND (SD.ShipCheckDate IS NULL OR SD.ShipCheckDate = '')





    AND (
        SD.ShipCheckDate >= DATE_FORMAT(#{pShipCheckStartDate}, '%Y-%m-%d') AND
        SD.ShipCheckDate <  ADDDATE(DATE_FORMAT(#{pShipCheckEndDate}, '%Y-%m-%d'), INTERVAL 1 DAY)
    )


AND SD.OrderNo = #{pOrderNo}
AND SD.OrderProdNo = #{pOrderProdNo}
AND SD.OrderChangeNo = #{pOrderChangeNo}
AND OrderType = #{pOrderType}
AND SD.ShopCode = #{pShopCode}
AND SD.OrderName LIKE CONCAT('%',#{pOrderName},'%')
AND SD.ChnlCode = #{pChnlCode}
AND Ch.ChnlName IN ('쿠팡','위메프','위메프D','위메프 파트너2.0','티몬','티몬(shopion)')
AND Ch.ChnlName NOT IN ('쿠팡','위메프','위메프D','위메프 파트너2.0','티몬','티몬(shopion)')

    AND Ch.ChnlName NOT IN ('홈앤쇼핑')
    AND Ch.ChnlName IN ('홈앤쇼핑')

AND SD.ShipCheckDate = #{pShipCheckDate}
ORDER BY 1

mapper.update:
UPDATE shopwizard.tShpShipDirect SET
    OrderState = #{orderState}, ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = #{changeDate}
    , ShipCheckDate = #{changeDate}
    , DeliCmpletDate = #{changeDate}
    , ShipCancelRqstDate = #{changeDate}
    , ShipCancelCmpletDate = #{changeDate}
WHERE OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}
AND OrderChangeNo = #{orderChangeNo}
AND OrderState = '출고지시'
AND OrderState = '배송시작'

UPDATE shopwizard.tShpShipDirectPrint SET
    OrderState = #{orderState}, ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = #{changeDate}
    , ShipCheckDate = #{changeDate}
    , DeliCmpletDate = #{changeDate}
    , ShipCancelRqstDate = #{changeDate}
    , ShipCancelCmpletDate = #{changeDate}
WHERE OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}
AND OrderChangeNo = #{orderChangeNo}
AND OrderState = '출고지시'
AND OrderState = '배송시작'

UPDATE shopwizard.tShpShipDirect SET
    OrderState = #{orderState}, ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = NOW(),
    ShipCancelRqstDate = NULL, ShipCancelCmpletDate = NULL, Remark = #{remark}
WHERE OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}
AND OrderChangeNo = #{orderChangeNo}

UPDATE shopwizard.tShpShipDirect SET
    DeliCompName = #{deliCompName},
    DeliCompCode = (SELECT DeliCompCode FROM shopwizard.tCmpDeliComp WHERE DeliCompName = #{deliCompName}),
    InvNo = #{invNo}, InvIdNo = #{invNo}, OrderState = #{orderState},
    ShipCmpletDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = NOW()
WHERE OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}
AND OrderChangeNo = #{orderChangeNo}
AND OrderState = '발주확인'

UPDATE shopwizard.tShpShipDirect SET
    AdjustSelectDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = NOW()
WHERE OrderNo = #{orderNo}
AND OrderProdNo = #{orderProdNo}
AND OrderChangeNo = #{orderChangeNo}

