mapper.select:
SELECT OrderNo, OrderProdNo, OrderChangeNo, OrderType, ChnlCode, ChnlOrderNo, ChnlOrderProdNo, OrderName, SupplyCode, SupplyName, ShopCode, ShopName, ProdCode, ProdName, MakerName, ModelName, ProdUnit, ProdMemo01, ItemCode, ItemName, ProdQty, SalePrice, SaleDiscntAmt, CustCpnDiscntAmt, ProdCpnDiscntAmt, PointUseAmt, SupplyPrice, DiscntSupplyPrice, BuyPrice, PointSaveAmt, VatRate, InvNo, OrderState, ShipCmpletDate, State, Remark, RegistId, RegistName, RegistDate, ChangeId, ChangeName, ChangeDate, Ch.ChnlName FROM shopwizard.tShpShipDirect INNER JOIN shopwizard.tCmpChnl Ch ON shopwizard.tShpShipDirect.ChnlCode = Ch.ChnlCode WHERE (ShipCmpletDate IS NOT NULL AND ShipCmpletDate != '') AND (AdjustSelectDate IS NULL OR AdjustSelectDate = '') AND Ch.SvcCode = #{pSvcCode}
AND ( ShipCmpletDate >= DATE_FORMAT(#{startDate}, '%Y%m%d') AND ShipCmpletDate < ADDDATE(DATE_FORMAT(#{endDate}, '%Y%m%d'), INTERVAL 1 DAY) )
AND ShopCode = #{pShopCode} AND OrderName LIKE CONCAT('%',#{pOrderName},'%') AND OrderState = #{pOrderState} UNION ALL SELECT OrderNo, OrderProdNo, OrderChangeNo, OrderType, ChnlCode, ChnlOrderNo, ChnlOrderProdNo, OrderName, SupplyCode, SupplyName, ShopCode, ShopName, ProdCode, ProdName, MakerName, ModelName, ProdUnit, ProdMemo01, ItemCode, ItemName, -1 * ProdQty, -1 * SalePrice, -1 * SaleDiscntAmt, -1 * CustCpnDiscntAmt, -1 * ProdCpnDiscntAmt, -1 * PointUseAmt, -1 * SupplyPrice, -1 * DiscntSupplyPrice, -1 * BuyPrice, -1 * PointSaveAmt, VatRate, InvNo, OrderState, ReturnCmpletDate AS ShipCmpletDate, State, Remark, RegistId, RegistName, RegistDate, ChangeId, ChangeName, ChangeDate, Ch.ChnlName FROM shopwizard.tShpReturnDirect INNER JOIN shopwizard.tCmpChnl Ch ON shopwizard.tShpReturnDirect.ChnlCode = Ch.ChnlCode WHERE (ReturnCmpletDate IS NOT NULL AND ReturnCmpletDate != '') AND (AdjustSelectDate IS NULL OR AdjustSelectDate = '') AND Ch.SvcCode = #{pSvcCode}
AND ( ReturnCmpletDate >= DATE_FORMAT(#{startDate}, '%Y%m%d') AND ReturnCmpletDate < ADDDATE(DATE_FORMAT(#{endDate}, '%Y%m%d'), INTERVAL 1 DAY) )
AND ShopCode = #{pShopCode} AND OrderName LIKE CONCAT('%',#{pOrderName},'%') AND OrderState = #{pOrderState} ORDER BY OrderNo DESC LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*) FROM (
    (SELECT OrderNo FROM shopwizard.tShpShipDirect
    WHERE (ShipCmpletDate IS NOT NULL AND ShipCmpletDate != '')
    AND (AdjustSelectDate IS NULL OR AdjustSelectDate = '')

        AND EXISTS ( SELECT * FROM shopwizard.tCmpChnl Ch WHERE shopwizard.tShpShipDirect.ChnlCode = Ch.ChnlCode AND Ch.SvcCode = #{pSvcCode} )



        AND (
            ShipCmpletDate >= DATE_FORMAT(#{startDate}, '%Y%m%d') AND
            ShipCmpletDate <  ADDDATE(DATE_FORMAT(#{endDate}, '%Y%m%d'), INTERVAL 1 DAY)
        )


    AND ShopCode = #{pShopCode}
    AND OrderName LIKE CONCAT('%',#{pOrderName},'%')
    AND OrderState = #{pOrderState}
    )
    UNION ALL
    (SELECT OrderNo FROM shopwizard.tShpReturnDirect
    WHERE (ReturnCmpletDate IS NOT NULL AND ReturnCmpletDate != '')

        AND EXISTS ( SELECT * FROM shopwizard.tCmpChnl Ch WHERE shopwizard.tShpReturnDirect.ChnlCode = Ch.ChnlCode AND Ch.SvcCode = #{pSvcCode} )



        AND (
            ReturnCmpletDate >= DATE_FORMAT(#{startDate}, '%Y%m%d') AND
            ReturnCmpletDate <  ADDDATE(DATE_FORMAT(#{endDate}, '%Y%m%d'), INTERVAL 1 DAY)
        )


    AND ShopCode = #{pShopCode}
    AND OrderName LIKE CONCAT('%',#{pOrderName},'%')
    AND OrderState = #{pOrderState}
    )
) t

SELECT * FROM ( SELECT OP.OrderNo, OP.OrderProdNo, 1 AS OrderChangeNo, '정상주문' AS OrderType, O.OrderName, OP.SupplyCode, OP.SupplyName, OP.ShopCode, OP.ShopName, OP.BundleYn, '' AS CateCode, '' AS StoreCode, OP.ProdCode, OP.ShopProdCode, OP.MakerName, OP.ModelName, OP.ProdUnit, OP.ProdMemo01, OP.ItemCode, OP.ProdName, OP.ItemName, OP.ProdImg, OP.ProdQty, OP.SalePrice, OP.SaleDiscntAmt, OP.CustCpnDiscntAmt, OP.ProdCpnDiscntAmt, OP.PointUseAmt, OP.SupplyPrice, OP.SupplyPrice AS DiscntSupplyPrice, OP.BuyPrice, OP.PointSaveAmt, OP.VatRate, OP.VatAmt, OP.DeliFeeAmt AS CustChrgDeliFee, OP.DeliFeeAmt, OP.DeliFeeId, OP.DeliFeeType, OP.DeliCompCode, OP.PrevInvNo, OP.InvNo, OP.ShipCmpletDate, OP.OrderState, O.ChnlCode, C.ChnlName, OP.ChnlOrderNo, OP.ChnlOrderProdNo, OP.State, OP.Remark, OP.RegistId, OP.RegistName, OP.RegistDate, OP.ChangeId, OP.ChangeName, OP.ChangeDate FROM shopion.tOrdOrderProd OP INNER JOIN shopion.tOrdOrder O ON O.OrderNo = OP.OrderNo INNER JOIN shopwizard.tCmpShop S ON S.ShopCode = OP.ShopCode INNER JOIN shopwizard.tCmpChnl C ON C.ChnlCode = O.ChnlCode WHERE ( OP.ShipCmpletDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND OP.ShipCmpletDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) ) AND OP.ShipAdjustDate IS NULL AND C.SvcCode = #{pSvcCode} AND S.SvcCode = #{pSvcCode} AND OP.ShopCode = #{pShopCode} AND S.adjustPeriodCode = #{pAdjustPeriodType} UNION ALL SELECT OP.OrderNo, OP.OrderProdNo, 2 AS OrderChangeNo, '환불주문' AS OrderType, O.OrderName, OP.SupplyCode, OP.SupplyName, OP.ShopCode, OP.ShopName, OP.BundleYn, '' AS CateCode, '' AS StoreCode, OP.ProdCode, OP.ShopProdCode, OP.MakerName, OP.ModelName, OP.ProdUnit, OP.ProdMemo01, OP.ItemCode, OP.ProdName, OP.ItemName, OP.ProdImg, -1 * OP.ProdQty, -1 * OP.SalePrice, -1 * OP.SaleDiscntAmt, -1 * OP.CustCpnDiscntAmt, -1 * OP.ProdCpnDiscntAmt, -1 * OP.PointUseAmt, -1 * OP.SupplyPrice, -1 * OP.SupplyPrice AS DiscntSupplyPrice, -1 * OP.BuyPrice, -1 * OP.PointSaveAmt, -1 * OP.VatRate, -1 * OP.VatAmt, -1 * OP.DeliFeeAmt AS CustChrgDeliFee, -1 * OP.DeliFeeAmt, OP.DeliFeeId, OP.DeliFeeType, OP.DeliCompCode, OP.PrevInvNo, OP.InvNo, OP.RefundCmpletDate AS ShipCmpletDate, OP.OrderState, O.ChnlCode, C.ChnlName, OP.ChnlOrderNo, OP.ChnlOrderProdNo, OP.State, OP.Remark, OP.RegistId, OP.RegistName, OP.RegistDate, OP.ChangeId, OP.ChangeName, OP.ChangeDate FROM shopion.tOrdOrderProd OP INNER JOIN shopion.tOrdOrder O ON O.OrderNo = OP.OrderNo INNER JOIN shopwizard.tCmpShop S ON S.ShopCode = OP.ShopCode INNER JOIN shopwizard.tCmpChnl C ON C.ChnlCode = O.ChnlCode WHERE ( OP.RefundCmpletDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND OP.RefundCmpletDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) ) AND OP.ShipCmpletDate IS NOT NULL AND OP.ShipCmpletDate != '' AND OP.RefundAdjustDate IS NULL AND C.SvcCode = #{pSvcCode} AND S.SvcCode = #{pSvcCode} AND OP.ShopCode = #{pShopCode} AND S.adjustPeriodCode = #{pAdjustPeriodType} ) T_ADJUST
ORDER BY ${sidx} ${sord} ORDER BY OrderNo DESC, OrderProdNo ASC
LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*) FROM (
    SELECT OP.OrderNo FROM shopion.tOrdOrderProd OP
    INNER JOIN shopion.tOrdOrder O ON O.OrderNo = OP.OrderNo
    INNER JOIN shopwizard.tCmpShop S ON S.ShopCode = OP.ShopCode
    INNER JOIN shopwizard.tCmpChnl C ON C.ChnlCode = O.ChnlCode
    WHERE
     ( OP.ShipCmpletDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND OP.ShipCmpletDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) ) 
    AND OP.ShipAdjustDate IS NULL
    AND C.SvcCode = #{pSvcCode}
    AND S.SvcCode = #{pSvcCode}
    AND OP.ShopCode = #{pShopCode}
    AND S.adjustPeriodCode = #{pAdjustPeriodType}
    UNION ALL
    SELECT OP.OrderNo FROM shopion.tOrdOrderProd OP
    INNER JOIN shopion.tOrdOrder O ON O.OrderNo = OP.OrderNo
    INNER JOIN shopwizard.tCmpShop S ON S.ShopCode = OP.ShopCode
    INNER JOIN shopwizard.tCmpChnl C ON C.ChnlCode = O.ChnlCode
    WHERE
     ( OP.RefundCmpletDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND OP.RefundCmpletDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY) ) 
    AND OP.RefundAdjustDate IS NULL
    AND C.SvcCode = #{pSvcCode}
    AND S.SvcCode = #{pSvcCode}
    AND OP.ShopCode = #{pShopCode}
    AND S.adjustPeriodCode = #{pAdjustPeriodType}
) T_ADJUST
